34	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
35	import org.springframework.samples.petclinic.rest.dto.PetDto;
36	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
37	import org.springframework.samples.petclinic.rest.dto.VisitDto;
38	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
39	import org.springframework.samples.petclinic.rest.validation.AddressNormalizer;
40	import org.springframework.samples.petclinic.rest.validation.DuplicateTelephoneException;
41	import org.springframework.samples.petclinic.rest.validation.EmailNormalizer;
42	import org.springframework.samples.petclinic.rest.validation.RegistrationDateNormalizer;
43	import org.springframework.samples.petclinic.rest.validation.TelephoneNormalizer;
44	import org.springframework.samples.petclinic.service.ClinicService;
45	import org.springframework.security.access.prepost.PreAuthorize;
46	import org.springframework.web.bind.annotation.CrossOrigin;
47	import org.springframework.web.bind.annotation.RequestMapping;
48	import org.springframework.web.bind.annotation.RestController;
49	import org.springframework.web.util.UriComponentsBuilder;
50	
51	import jakarta.transaction.Transactional;
52	
53	/**
54	 * @author Vitaliy Fedoriv
55	 */
56	
57	@RestController
58	@CrossOrigin(exposedHeaders = "errors, content-type")
59	@RequestMapping("/api")
60	public class OwnerRestControllerV1 implements OwnersApi {
61	
62	    private final ClinicService clinicService;
63	
64	    private final OwnerMapper ownerMapper;
65	
66	    private final PetMapper petMapper;
67	
68	    private final VisitMapper visitMapper;
69	
70	    public OwnerRestControllerV1(ClinicService clinicService,
71	                                 OwnerMapper ownerMapper,
72	                                 PetMapper petMapper,
73	                                 VisitMapper visitMapper) {
74	        this.clinicService = clinicService;
75	        this.ownerMapper = ownerMapper;
76	        this.petMapper = petMapper;
77	        this.visitMapper = visitMapper;
78	    }
79	
80	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
81	    @Override
82	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
83	        Collection<Owner> owners;
84	        if (lastName != null) {
85	            owners = this.clinicService.findOwnerByLastName(lastName);
86	        } else {
87	            owners = this.clinicService.findAllOwners();
88	        }
89	        if (owners.isEmpty()) {
90	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
91	        }
92	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
93	    }
94	
95	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
96	    @Override
97	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
98	        Owner owner = this.clinicService.findOwnerById(ownerId);
99	        if (owner == null) {
100	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
101	        }
102	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
103	    }
104	
105	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
106	    @Override
107	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
108	        HttpHeaders headers = new HttpHeaders();
109	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
110	        String telephone = TelephoneNormalizer.normalize(owner.getTelephone());
111	        owner.setTelephone(telephone);
112	        owner.setEmail(EmailNormalizer.normalize(owner.getEmail()));
113	        owner.setAddress(AddressNormalizer.normalize(owner.getAddress()));
114	        LocalDate effectiveRegistrationDate =
115	            owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
116	        owner.setRegistrationDate(RegistrationDateNormalizer.normalize(effectiveRegistrationDate));
117	        boolean telephoneInUse = this.clinicService.findAllOwners().stream()
118	            .anyMatch(existing -> telephone.equals(TelephoneNormalizer.toE164(existing.getTelephone())));
119	        if (telephoneInUse) {
120	            throw new DuplicateTelephoneException(
121	                "telephone " + telephone + " is already used by another owner");
122	        }
123	        this.clinicService.createOwner(owner, Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold()));
124	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
125	        headers.setLocation(UriComponentsBuilder.newInstance()
126	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
127	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
128	    }
129	
130	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
131	    @Override
132	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
133	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
134	        if (currentOwner == null) {
135	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
136	        }
137	        currentOwner.setAddress(ownerFieldsDto.getAddress());
138	        currentOwner.setCity(ownerFieldsDto.getCity());
139	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
140	        currentOwner.setLastName(ownerFieldsDto.getLastName());
141	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
142	        currentOwner.setEmail(EmailNormalizer.normalize(ownerFieldsDto.getEmail()));
143	        this.clinicService.saveOwner(currentOwner);
144	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
145	    }
146	
147	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
148	    @Transactional
149	    @Override
150	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
151	        Owner owner = this.clinicService.findOwnerById(ownerId);
152	        if (owner == null) {
153	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
154	        }
155	        this.clinicService.deleteOwner(owner);
156	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
157	    }
158	
159	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
160	    @Override
161	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
162	        Owner owner = this.clinicService.findOwnerById(ownerId);
163	        if (owner == null) {
164	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
165	        }
166	        HttpHeaders headers = new HttpHeaders();
167	        Pet pet = petMapper.toPet(petFieldsDto);
168	        owner.setId(ownerId);
169	        pet.setOwner(owner);
170	        pet.getType().setName(null);
171	        this.clinicService.savePet(pet);
172	        PetDto petDto = petMapper.toPetDto(pet);
173	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
174	            .buildAndExpand(pet.getId()).toUri());
175	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
176	    }
177	
178	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
179	    @Override
180	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
181	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
182	        if (currentOwner != null) {
183	            Pet currentPet = this.clinicService.findPetById(petId);
184	            if (currentPet != null) {
185	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
186	                currentPet.setName(petFieldsDto.getName());
187	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
188	                this.clinicService.savePet(currentPet);
189	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
190	            }
191	        }
192	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
193	    }
194	
195	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
196	    @Override
197	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
198	        HttpHeaders headers = new HttpHeaders();
199	        Visit visit = visitMapper.toVisit(visitFieldsDto);
200	        Pet pet = new Pet();
201	        pet.setId(petId);
202	        visit.setPet(pet);
203	        this.clinicService.saveVisit(visit);
204	        VisitDto visitDto = visitMapper.toVisitDto(visit);
205	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
206	            .buildAndExpand(visit.getId()).toUri());
207	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
208	    }
209	
210	
211	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
212	    @Override
213	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
214	        Owner owner = this.clinicService.findOwnerById(ownerId);
215	        if (owner != null) {
216	            Pet pet = owner.getPet(petId);
217	            if (pet != null) {
218	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
219	            }
220	        }
221	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
222	    }
223	}
