291	        String lastName = IdentityNormalizer.normalize(owner.getLastName());
292	        String address = AddressNormalizer.canonical(owner.getAddress());
293	        List<Owner> householdMembers = ownerRepository.findAll().stream()
294	            .filter(existing -> lastName.equals(IdentityNormalizer.normalize(existing.getLastName()))
