274	    /**
275	     * Handles exception thrown by Bean Validation on controller methods parameters
276	     *
277	     * @param e The {@link MethodArgumentNotValidException} to be handled
278	     * @param request {@link HttpServletRequest} object referring to the current request.
279	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
280	     */
281	    @ExceptionHandler(MethodArgumentNotValidException.class)
282	    @ResponseBody
283	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
284	        HttpStatus status = HttpStatus.BAD_REQUEST;
285	        BindingErrorsResponse errors = new BindingErrorsResponse();
286	        BindingResult bindingResult = e.getBindingResult();
287	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
288	        if (bindingResult.hasErrors()) {
289	            errors.addAllErrors(bindingResult);
290	            List<String> errorFields = bindingResult.getFieldErrors().stream()
291	                .map(fieldError -> fieldError.getField())
292	                .distinct()
293	                .toList();
294	            detail.setProperty("errors", errorFields);
295	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
296	                .map(fieldError -> {
297	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
298	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
299	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
300	                        fieldError.getField(),
301	                        defaultMessage,
302	                        rejectedValue);
303	                    return new ValidationMessageDto(message)
304	                        .putAdditionalProperty("field", fieldError.getField())
305	                        .putAdditionalProperty("rejectedValue", rejectedValue)
306	                        .putAdditionalProperty("defaultMessage", defaultMessage);
307	                })
308	                .toList();
309	            logger.debug("Validation error at {} {}: {}",
310	                request.getMethod(),
311	                request.getRequestURI(),
312	                bindingResult.getFieldErrors());
313	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
314	            return ResponseEntity.status(status).body(detail);
315	        }
316	        return ResponseEntity.status(status).body(detail);
317	    }
