63	    /**
64	     * Formats the owner's membership number as {@code '<customerCode>-M<YY>'}: the customer
65	     * code, the literal {@code '-M'}, and the last two digits of the registrationDate year.
66	     * Returns {@code null} unless both the customer code and registration date are present.
67	     */
68	    default String membershipNumber(Owner owner) {
69	        if (owner == null || owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
70	            return null;
