18	
19	/**
20	 * Utility for normalizing telephone numbers into
21	 * <a href="https://en.wikipedia.org/wiki/E.164">E.164</a> form.
22	 *
23	 * <p>Spaces, dashes and brackets are stripped. When the value already carries a
24	 * leading {@code '+'} the country code is kept as supplied; otherwise the country
25	 * code {@code '+61'} is assumed and a single leading {@code '0'} is dropped from the
26	 * national digits. The result must contain between 8 and 15 digits after the
27	 * {@code '+'}; anything else raises an {@link InvalidTelephoneException} so the
28	 * request is rejected with {@code 400 Bad Request}. For example {@code '0412 345 678'}
29	 * becomes {@code '+61412345678'}.
30	 */
31	public final class TelephoneNormalizer {
32	
33	    private static final String DEFAULT_COUNTRY_CODE = "61";
34	
35	    private static final int MIN_DIGITS = 8;
36	
37	    private static final int MAX_DIGITS = 15;
38	
39	    private TelephoneNormalizer() {
40	    }
41	
42	    /**
43	     * Normalize the supplied telephone into E.164 form.
44	     *
45	     * @param telephone the raw telephone value (may be {@code null})
46	     * @return the normalized E.164 telephone (a leading {@code '+'} followed by digits)
47	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
48	     */
49	    public static String normalize(String telephone) {
50	        String e164 = toE164(telephone);
51	        if (e164 == null) {
52	            throw new InvalidTelephoneException(
53	                "telephone must be a valid E.164 number (8 to 15 digits after the '+')");
54	        }
55	        return e164;
56	    }
57	
58	    /**
59	     * Best-effort conversion of the supplied telephone into E.164 form, returning
60	     * {@code null} instead of throwing when the value cannot form a valid E.164 number.
61	     * Useful for comparing telephones that may already be stored in a non-normalized form.
62	     *
63	     * @param telephone the raw telephone value (may be {@code null})
64	     * @return the E.164 telephone, or {@code null} if it cannot be formed
65	     */
66	    public static String toE164(String telephone) {
67	        if (telephone == null) {
68	            return null;
69	        }
70	        String cleaned = telephone.replaceAll("[\\s\\-()\\[\\]]", "");
71	        String digits;
72	        if (cleaned.startsWith("+")) {
73	            digits = cleaned.substring(1);
74	        }
75	        else {
76	            String national = cleaned;
77	            if (national.startsWith("0")) {
78	                national = national.substring(1);
79	            }
80	            digits = DEFAULT_COUNTRY_CODE + national;
81	        }
82	        if (!digits.matches("\\d+")) {
83	            return null;
84	        }
85	        if (digits.length() < MIN_DIGITS || digits.length() > MAX_DIGITS) {
86	            return null;
87	        }
88	        return "+" + digits;
89	    }
90	}
