21	/**
22	 * Utility for canonicalizing an owner identity field (such as last name or address) so two
23	 * values can be compared for the household-duplicate rule. Comparison is case-insensitive and
24	 * ignores differences in surrounding and internal whitespace: the value is trimmed, internal
25	 * whitespace runs are collapsed to a single space, and the result is lower-cased. A {@code null}
26	 * value normalizes to an empty string.
27	 */
28	public final class IdentityNormalizer {
29	
30	    private IdentityNormalizer() {
31	    }
32	
33	    /**
34	     * Normalize the supplied identity value for equality comparison.
35	     *
36	     * @param value the raw identity value (may be {@code null})
37	     * @return the trimmed, whitespace-collapsed, lower-cased value, or an empty string when {@code null}
38	     */
39	    public static String normalize(String value) {
40	        if (value == null) {
41	            return "";
42	        }
43	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
44	    }
